"""OpenWrt Router: puts the device in the OpenBridge graph (generated by `openbridge partner new`).
Identity is a salted pseudonym of the serial; the raw serial never reaches the snapshot."""
from src.fabric.contracts import Capability, DeviceObservation, Identifier, Link, now, opaque


def ingest_openwrt_router(registry, device, salt, serial, emulated=True):
    status = 'SIMULATED_VERIFIED' if emulated else 'IMPLEMENTED_UNVERIFIED'
    t = now()
    try:
        facts = device.facts()
    except Exception as error:
        return {'status': 'UNAVAILABLE', 'detail': type(error).__name__}
    obs = [DeviceObservation(f['name'], f['value'], 'OPENWRT_ROUTER', 'LAN', t, True) for f in facts]
    key = registry.upsert([Identifier('openwrt_router_serial', opaque('openwrt_router_serial', serial, salt), True)],
                          category='router', label='OpenWrt Router', observations=obs)
    registry.link(Link('pc', key, 'LAN', ('observe', 'read', 'control'), 'OPENWRT_ROUTER'))
    registry.capability(key, Capability('openwrt_router_status', 'read', status, 'OPENWRT_ROUTER', 'facts read from the device'))
    registry.capability(key, Capability('openwrt_router_setting', 'write', status, 'OPENWRT_ROUTER', 'typed settings, read back, exact Undo'))
    registry.capability(key, Capability('openwrt_router_command', 'write', status, 'OPENWRT_ROUTER', 'momentary commands, consent per command'))
    return {'status': 'OK', 'devices': 1, 'emulated': emulated}
